Context("Fraction"); $var = list_random('a'..'n','p'..'z','A'..'D', 'F'..'N','P'..'T','V'..'Z'); Context()->variables->are($var => 'Real'); do { ($a, $b) = (-20..-2,2..20)[NchooseK(38,2)]; } until ($b % $a != 0); $left = Formula("$a*$var")->reduce; $right = Formula("$b")->reduce; ($left, $right) = ($left, $right)[NchooseK(2,2)]; $solution = Fraction($b, $a); Context("FiniteSolutionSets"); Context()->variables->are($var => 'Real'); $solset = Formula("{$solution}");
